import {
	FrameItem,
} from './data-types';
import {
	FileName,
} from './components/file-name';
import * as React from 'react';

interface Props {
	frame: FrameItem;
	expanded?: boolean;
	isFileName?: boolean;
}

export const Frame = ( { frame, expanded, isFileName }: Props ) => (
	<>
		<FileName
			text={ frame.display }
			file={ frame.file }
			line={ frame.line }
			isFileName={ isFileName }
			expanded={ expanded }
		/>
	</>
);
